CREATE TABLE "public"."measurements" (
  "id"     bigint GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "name"   text   NOT NULL,
  "symbol" text   NOT NULL,
  CONSTRAINT "measurements_pkey" PRIMARY KEY (id)
);

ALTER TABLE "public"."measurements"
  ENABLE ROW LEVEL SECURITY;

CREATE POLICY "app_all_measurements" ON "public"."measurements"
  FOR ALL
  TO "anon", "authenticated"
  USING (true)
  WITH CHECK (true);

REVOKE ALL ON SEQUENCE "public"."measurements_id_seq" FROM "anon";

GRANT SELECT, UPDATE, USAGE ON SEQUENCE "public"."measurements_id_seq" TO "anon";

REVOKE ALL ON SEQUENCE "public"."measurements_id_seq" FROM "authenticated";

GRANT SELECT, UPDATE, USAGE ON SEQUENCE "public"."measurements_id_seq" TO "authenticated";

REVOKE ALL ON SEQUENCE "public"."measurements_id_seq" FROM "postgres";

GRANT SELECT, UPDATE, USAGE ON SEQUENCE "public"."measurements_id_seq" TO "postgres";

REVOKE ALL ON SEQUENCE "public"."measurements_id_seq" FROM "service_role";

GRANT SELECT, UPDATE, USAGE ON SEQUENCE "public"."measurements_id_seq" TO "service_role";

GRANT DELETE, INSERT, MAINTAIN, REFERENCES, SELECT, TRIGGER, TRUNCATE, UPDATE ON TABLE "public"."measurements" TO "anon", "authenticated";

GRANT DELETE, INSERT, MAINTAIN, REFERENCES, SELECT, TRIGGER, TRUNCATE, UPDATE ON TABLE "public"."measurements" TO "service_role";

REVOKE ALL ON TABLE "public"."measurements" FROM "postgres";

GRANT DELETE, INSERT, MAINTAIN, REFERENCES, SELECT, TRIGGER, TRUNCATE, UPDATE ON TABLE "public"."measurements" TO "postgres";
